eq(base.strides,{4,1},"ifftshift/int8/(3, 2)/1/base:get(np.s(),np.s(1,nil,2)): backing state: strides")
eq(base.dtype,"int8","ifftshift/int8/(3, 2)/1/base:get(np.s(),np.s(1,nil,2)): backing state: dtype")
cases=cases+1
end
